import{_ as e,o as s,c as t,ae as i}from"./chunks/framework.C4zpkcTP.js";const m=JSON.parse('{"title":"Installation","description":"Install Laravel Myanmar NRC, run its migrations and seed the NRC data.","frontmatter":{"title":"Installation","description":"Install Laravel Myanmar NRC, run its migrations and seed the NRC data."},"headers":[],"relativePath":"laravel-myanmar-nrc/installation.md","filePath":"laravel-myanmar-nrc/installation.md"}'),n={name:"laravel-myanmar-nrc/installation.md"};function l(r,a,o,d,h,p){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/laravel-myanmar-nrc</span></span></code></pre></div><p>The service provider and the <code>MyanmarNrc</code> facade alias are registered automatically.</p><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><p>The package loads its migrations automatically. Run them to create the <code>nrc_states</code>, <code>nrc_townships</code> and <code>nrc_types</code> tables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>Seed them from the bundled <a href="https://github.com/laranex/laravel-myanmar-nrc/blob/master/resources/data/nrc.json" target="_blank" rel="noreferrer">NRC data</a>, or from your own file (see <a href="/laravel-myanmar-nrc/configuration.html">Configuration</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mm-nrc:seed</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>mm-nrc:seed</code> empties the three NRC tables before inserting. It works on every database driver and throws <code>InvalidJsonFileException</code> when the data file is missing or malformed.</p></div><p>To change the table definitions, publish the migrations before running them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;laravel-myanmar-nrc-migrations&quot;</span></span></code></pre></div><p>Once a migration is published, the package stops loading its own copy, so the tables are never created twice. Publishing again reuses the copies you already have. Don&#39;t publish them in an application that already ran the package migrations: the published files have new names, so <code>migrate</code> would try to create the existing tables again.</p><p>The database is only needed when <code>db_driven</code> is <code>true</code> (the default). With <code>db_driven</code> set to <code>false</code>, NRCs are read from the JSON file and you can skip the migration and seeding.</p>',13)])])}const g=e(n,[["render",l]]);export{m as __pageData,g as default};
